SET client_encoding = 'UTF8';

DO $$
DECLARE
  v_admin_id UUID;
  v_articulo_id UUID;
BEGIN
  SELECT id INTO v_admin_id FROM perfiles WHERE rol_id = 1 LIMIT 1;
  IF v_admin_id IS NULL THEN
    SELECT id INTO v_admin_id FROM perfiles LIMIT 1;
  END IF;

  DELETE FROM articulos WHERE slug = 'cuatro-esquinas';

  v_articulo_id := uuid_generate_v4();

  INSERT INTO articulos (
    id,
    autor_id,
    categoria_id,
    titulo,
    slug,
    contenido,
    extracto,
    imagen_destacada,
    estado,
    etiquetas,
    metadata
  ) VALUES (
    v_articulo_id,
    v_admin_id,
    NULL,
    'Cuatro Esquinas',
    'cuatro-esquinas',
    $html$<h2>📜 Descripción del Juego</h2>
<p><strong>Cuatro Esquinas</strong> es un vibrante juego scout de campo abierto que combina la velocidad de carrera, la estrategia de lanzamientos y la agilidad de recolección en equipo. Dos patrullas se enfrentan en un cuadrilátero delimitado para desafiar sus reflejos y coordinación.</p>

<hr>

<h3>🎲 ¿Cómo se juega?</h3>
<ol>
  <li><strong>Delimitación del Terreno:</strong> Se delimita un cuadrado de 15 metros por lado colocados en las esquinas cuatro pañolines sobre el césped.</li>
  <li><strong>Formación de Equipos:</strong> El Equipo A (corredores) se alinea fuera del cuadrado en una fila. El Equipo B (defensores) se dispersa tácticamente por el terreno.</li>
  <li><strong>Lanzamiento y Carrera:</strong> El primer corredor del Equipo A lanza la pelota lo más lejos posible dentro del campo y comienza a correr a máxima velocidad alrededor del cuadrado para tocar los cuatro pañolines de las esquinas.</li>
  <li><strong>La Interceptación:</strong> Los defensores del Equipo B deben tomar la pelota lo más rápido posible y, pasándola entre ellos sin dar pasos sosteniendo el balón, intentar quemar o tocar al corredor antes de que complete el recorrido por las cuatro esquinas.</li>
  <li><strong>Rotación:</strong> Una vez que han corrido todos los integrantes de un equipo, se intercambian los roles. Gana el equipo que logre recolectar la mayor cantidad de pañolines completando carreras limpias.</li>
</ol>$html$,
    'Un vibrante juego scout de campo abierto donde dos equipos compiten lanzando la pelota y corriendo por las esquinas del terreno.',
    '/uploads/actividad_cuatroEsquinas.webp',
    'publicado',
    ARRAY['juego-fisico', 'carrera', 'equipo', 'panolines', 'exterior'],
    $json${"unidades": ["manada", "compañía", "tropa", "avanzada"], "duracion": "20 minutos", "cantidad": "16 participantes", "lugares": ["Exterior", "campo delimitado"], "materiales": ["Pañolines", "Pelota"], "areas": ["Corporalidad", "Carácter", "Sociabilidad"], "objetivos": ["Refuerzo de habilidades físicas", "Favorecer el trabajo en equipo", "Estimular la capacidad de reacción", "Estrategia y planificación"], "justificacion_areas": "Cuatro Esquinas estimula la corporalidad al ejercitar la velocidad de aceleración, la precisión de pases y la resistencia física. Fortalece el carácter al promover el sentido del humor y el fair play ante la presión de la carrera, y desarrolla la sociabilidad al afianzar la coordinación táctica y la cooperación entre compañeros.", "variaciones": "Cuatro Esquinas por Parejas: Los corredores avanzan tomados de la mano, exigiendo una aceleración y coordinación sincronizada entre ambos participantes.\n\nCarrera Nocturna con Linternas: Se juega al anochecer iluminando únicamente las esquinas con linternas de campamento para agudizar los sentidos.\n\nLanzamiento de Pañolín Lastrado: En lugar de una pelota, se utiliza un pañolín con un nudo pesado para exigir precisión en los pases.", "recomendaciones": "Seguridad y Pases Limpios: Exigir firmemente que los lanzamientos para tocar al corredor sean suaves y dirigidos del torso hacia abajo. Jamás se permiten lanzamientos a la cabeza.\n\nTerreno Despejado: Inspeccionar previamente que el cuadrilátero esté libre de piedras o irregularidades que puedan provocar tropezones durante la carrera.\n\nAnimación en Equipo: Motivar a los jugadores en reserva a cantar y animar a sus compañeros de fila durante cada carrera.", "objetivos_educativos": [{"id": "4bf1e3dd-7f21-4c24-962d-9d6d64e32f25", "texto": "Me gusta hacer actividades al aire libre.", "texto_terminal": "Convive constantemente en la naturaleza y participa en actividades deportivas y recreativas.", "rango_edad": "Infancia Media", "area": "Corporalidad", "unidad": "Manada", "como_se_cumple": "Corriendo velozmente entre las bases para alcanzar los pañolines en el tiempo límite."}, {"id": "5d2d48ed-c461-4a8e-9048-cceecd3de2e2", "texto": "Me gusta jugar con otros niños y niñas y respeto las reglas de los juegos.", "texto_terminal": "Convive constantemente en la naturaleza y participa en actividades deportivas y recreativas.", "rango_edad": "Infancia Tardía", "area": "Corporalidad", "unidad": "Manada", "como_se_cumple": "Ejercitando mi velocidad de aceleración y puntería de lanzamiento al aire libre."}, {"id": "58b4936a-816e-4d17-8d0a-c92d0606009d", "texto": "Participo en los juegos, excursiones y campamentos que organiza mi patrulla.", "texto_terminal": "Convive constantemente en la naturaleza y participa en actividades deportivas y recreativas.", "rango_edad": "11 a 13 años", "area": "Corporalidad", "unidad": "Tropa", "como_se_cumple": "Desarrollando resistencia física y velocidad de reacción en las carreras por equipo."}, {"id": "6768d60a-187e-4bbf-97b9-cdc25a316030", "texto": "Ayudo a preparar los juegos, excursiones y campamentos de mi patrulla y mi Tropa.", "texto_terminal": "Convive constantemente en la naturaleza y participa en actividades deportivas y recreativas.", "rango_edad": "13 a 15 años", "area": "Corporalidad", "unidad": "Tropa", "como_se_cumple": "Esforzándome por superar mi rendimiento físico respetando el fair play."}, {"id": "d5b111f1-5f6f-4716-8a02-e1826d653c59", "texto": "Participo en los juegos, excursiones y campamentos que organiza mi patrulla.", "texto_terminal": "Convive constantemente en la naturaleza y participa en actividades deportivas y recreativas.", "rango_edad": "11 a 13 años", "area": "Corporalidad", "unidad": "Compañía", "como_se_cumple": "Demostrando agilidad corporal y coordinación de pases con la pelota."}, {"id": "b12da732-d736-480c-82b8-95b312316390", "texto": "Me esfuerzo por mejorar mi rendimiento en el deporte que practico y sé ganar y perder.", "texto_terminal": "Convive constantemente en la naturaleza y participa en actividades deportivas y recreativas.", "rango_edad": "13 a 15 años", "area": "Corporalidad", "unidad": "Compañía", "como_se_cumple": "Coordinando desplazamientos rápidos y estrategias de interceptación."}, {"id": "7200435f-b020-46fc-b323-8249048b1d18", "texto": "Participo en la organización de juegos y actividades recreativas para los demás.", "texto_terminal": "Convive constantemente en la naturaleza y participa en actividades deportivas y recreativas.", "rango_edad": "15 a 17 años", "area": "Corporalidad", "unidad": "Avanzada", "como_se_cumple": "Liderando dinámicas de competencia deportiva intensa en el grupo."}, {"id": "8c1cbf88-6e1d-496b-b789-9e0b767c8814", "texto": "Casi siempre estoy alegre.", "texto_terminal": "Enfrenta la vida con alegría y sentido del humor.", "rango_edad": "Infancia Media", "area": "Carácter", "unidad": "Manada", "como_se_cumple": "Disfrutando con alegría del juego de carreras sin importar quién gane la ronda."}, {"id": "d408da3c-207d-4442-a891-8f50efbeecb1", "texto": "Enfrento las dificultades con buen ánimo.", "texto_terminal": "Enfrenta la vida con alegría y sentido del humor.", "rango_edad": "Infancia Tardía", "area": "Carácter", "unidad": "Manada", "como_se_cumple": "Manteniendo un espíritu alegre y entusiasta al recorrer las esquinas."}, {"id": "4d66ed86-48ec-4801-bd0a-e5c8d023c8cd", "texto": "Enfrento y resuelvo mis dificultades con alegría.", "texto_terminal": "Enfrenta la vida con alegría y sentido del humor.", "rango_edad": "11 a 13 años", "area": "Carácter", "unidad": "Tropa", "como_se_cumple": "Aceptando los resultados de cada carrera con sentido del humor y deportividad."}, {"id": "9a38e454-f93a-40a5-9f68-e500ba7e0655", "texto": "Comparto mi alegría con mis amigos, amigos y familia.", "texto_terminal": "Enfrenta la vida con alegría y sentido del humor.", "rango_edad": "13 a 15 años", "area": "Carácter", "unidad": "Tropa", "como_se_cumple": "Animando con energía a los compañeros de equipo durante sus lanzamientos."}, {"id": "117bbf3f-7e3d-4c61-b305-821609bf2e5a", "texto": "Contribuyo al ambiente de alegría de mi Compañía.", "texto_terminal": "Enfrenta la vida con alegría y sentido del humor.", "rango_edad": "11 a 13 años", "area": "Carácter", "unidad": "Compañía", "como_se_cumple": "Viviendo la competencia fraterna con optimismo y desinhibición."}, {"id": "25b24d3a-9d47-44af-b460-680508e644f3", "texto": "Soy alegre.", "texto_terminal": "Enfrenta la vida con alegría y sentido del humor.", "rango_edad": "13 a 15 años", "area": "Carácter", "unidad": "Compañía", "como_se_cumple": "Afrontando los momentos intensos del juego con madurez y buen ánimo."}, {"id": "4b2e406f-2d78-4039-9ce2-4ccb743eb553", "texto": "Soy capaz de reírme de mis propios absurdos.", "texto_terminal": "Enfrenta la vida con alegría y sentido del humor.", "rango_edad": "15 a 17 años", "area": "Carácter", "unidad": "Avanzada", "como_se_cumple": "Propiciando un clima festivo de camaradería y juego limpio."}, {"id": "cfa10133-c25c-4deb-aebe-a00f8fe3f7ef", "texto": "Comparto lo que tengo con mis compañeros y compañeras.", "texto_terminal": "Vive su libertad de un modo solidario, ejerciendo sus derechos, cumpliendo sus obligaciones y defendiendo igual derecho para los demás.", "rango_edad": "Infancia Media", "area": "Sociabilidad", "unidad": "Manada", "como_se_cumple": "Respetando los turnos de carrera de todos los lobatos de la seisena."}, {"id": "5cbe35dc-d15b-4070-9a36-5b0e652c7946", "texto": "Respeto las opiniones de los demás.", "texto_terminal": "Vive su libertad de un modo solidario, ejerciendo sus derechos, cumpliendo sus obligaciones y defendiendo igual derecho para los demás.", "rango_edad": "Infancia Tardía", "area": "Sociabilidad", "unidad": "Manada", "como_se_cumple": "Apoyando y colaborando con los compañeros para completar la recolección."}, {"id": "a3d7abdf-ca3b-42b8-92b5-403958fb537c", "texto": "Procuro que respetemos a nuestras compañeros, cualquiera sea su manera de ser.", "texto_terminal": "Vive su libertad de un modo solidario, ejerciendo sus derechos, cumpliendo sus obligaciones y defendiendo igual derecho para los demás.", "rango_edad": "11 a 13 años", "area": "Sociabilidad", "unidad": "Tropa", "como_se_cumple": "Respetando las decisiones de los árbitros y las reglas del cuadrilátero."}, {"id": "0d3af46a-d64c-4e59-a765-1f72dc41ba76", "texto": "Ayudo a mi patrulla en los compromisos que tomamos.", "texto_terminal": "Vive su libertad de un modo solidario, ejerciendo sus derechos, cumpliendo sus obligaciones y defendiendo igual derecho para los demás.", "rango_edad": "13 a 15 años", "area": "Sociabilidad", "unidad": "Tropa", "como_se_cumple": "Fomentando la inclusión activa y la cooperación táctica en la patrulla."}, {"id": "fce82191-77ea-444b-89d9-e33b62a323a5", "texto": "Procuro que respetemos a nuestras compañeras, cualquiera sea su manera de ser.", "texto_terminal": "Vive su libertad de un modo solidario, ejerciendo sus derechos, cumpliendo sus obligaciones y defendiendo igual derecho para los demás.", "rango_edad": "11 a 13 años", "area": "Sociabilidad", "unidad": "Compañía", "como_se_cumple": "Promoviendo el trabajo en equipo y el apoyo recíproco en el campo."}, {"id": "944660c8-0093-4181-ba2c-5f95cc74ba47", "texto": "No me gusta cuando no se respetan los derechos humanos y lo digo.", "texto_terminal": "Vive su libertad de un modo solidario, ejerciendo sus derechos, cumpliendo sus obligaciones y defendiendo igual derecho para los demás.", "rango_edad": "13 a 15 años", "area": "Sociabilidad", "unidad": "Compañía", "como_se_cumple": "Velando por el cumplimiento honesto de las reglas del juego."}, {"id": "5abfbe81-75e4-4444-b52d-38e59e8b6ec7", "texto": "Estoy siempre disponible para ayudar a los demás, incluso cuando se trata de tareas pesadas o poco agradables.", "texto_terminal": "Vive su libertad de un modo solidario, ejerciendo sus derechos, cumpliendo sus obligaciones y defendiendo igual derecho para los demás.", "rango_edad": "15 a 17 años", "area": "Sociabilidad", "unidad": "Avanzada", "como_se_cumple": "Organizando el juego con sentido de justicia y respeto solidario por todos."}]}$json$::jsonb
  );

  -- Categoría Hija: Juegos (ID: 7), Categoría Padre: Actividades (ID: 1)
  INSERT INTO articulo_categorias (articulo_id, categoria_id) VALUES (v_articulo_id, 7) ON CONFLICT DO NOTHING;
  INSERT INTO articulo_categorias (articulo_id, categoria_id) VALUES (v_articulo_id, 1) ON CONFLICT DO NOTHING;

END $$;



-- ==============================================
-- ARTICLE: los-submarinos
-- ==============================================
SET client_encoding = 'UTF8';

DO $$
DECLARE
  v_admin_id UUID;
  v_articulo_id UUID;
BEGIN
  SELECT id INTO v_admin_id FROM perfiles WHERE rol_id = 1 LIMIT 1;
  IF v_admin_id IS NULL THEN
    SELECT id INTO v_admin_id FROM perfiles LIMIT 1;
  END IF;

  DELETE FROM articulos WHERE slug = 'los-submarinos';

  v_articulo_id := uuid_generate_v4();

  INSERT INTO articulos (
    id,
    autor_id,
    categoria_id,
    titulo,
    slug,
    contenido,
    extracto,
    imagen_destacada,
    estado,
    etiquetas,
    metadata
  ) VALUES (
    v_articulo_id,
    v_admin_id,
    NULL,
    'Los Submarinos',
    'los-submarinos',
    $html$<h2>📜 Descripción del Juego</h2>
<p><strong>Los Submarinos</strong> es un apasionante juego scout de confianza, comunicación no verbal y táctica de patrulla. En él, cada equipo forma una "tripulación" que debe navegar por el terreno de juego con los ojos vendados, confiando ciegamente en la guía silenciosa o verbal de su capitán posicionado al final de la fila.</p>

<hr>

<h3>🎲 ¿Cómo se juega?</h3>
<ol>
  <li><strong>Formación de la Tripulación:</strong> Cada patrulla o seisena forma una fila india tomándose firmemente de la cintura o de los hombros.</li>
  <li><strong>La Venda del Pañolín:</strong> Todos los participantes de la fila se cubren los ojos con sus <strong>pañolines</strong> para quedar completamente a ciegas, a excepción del último participante (el Capitán del Submarino).</li>
  <li><strong>Navegación y Objetivo:</strong> El objetivo de cada submarino es maniobrar por el campo para envolver o interceptar el centro de los submarinos rivales, evitando a su vez ser envuelto por los demás.</li>
  <li><strong>El Código del Capitán:</strong> El capitán guía la nave utilizando comandos de voz ("¡Avante!", "¡Virar a la derecha!", "¡Detenerse!") o mediante toques táctiles en los hombros del compañero de enfrente, quienes transmiten la señal en cadena hacia el participante que encabeza la fila.</li>
  <li><strong>Victoria:</strong> El submarino que demuestre mayor agilidad de maniobra, mantenga su fila unida y logre cercar a sus oponentes sin romper la cadena gana la ronda.</li>
</ol>$html$,
    'Un apasionante juego scout de confianza y coordinación donde equipos a ciegas navegan guiados por su capitán.',
    '/uploads/actividad_losSubmarinos.webp',
    'publicado',
    ARRAY['juego-de-confianza', 'trabajo-en-equipo', 'panolines', 'exterior', 'patrulla'],
    $json${"unidades": ["manada", "compañía", "tropa", "avanzada", "clan"], "duracion": "25 minutos", "cantidad": "16 participantes", "lugares": ["Exterior", "campo abierto"], "materiales": ["Pañolines"], "areas": ["Sociabilidad", "Carácter", "Corporalidad"], "objetivos": ["Estimular la confianza", "Favorecer el trabajo en equipo", "Estimular la agilidad mental", "Fomentar la comunicación en el grupo"], "justificacion_areas": "Los Submarinos promueve la sociabilidad al consolidar la confianza mutua y la comunicación efectiva en equipo. Desarrolla el carácter al ejercitar la serenidad, la deportividad y el liderazgo responsable ante situaciones de incertidumbre visual, y estimula la corporalidad al requerir orientación espacial, coordinación postural y marcha sincronizada.", "variaciones": "<b>Navegación Silenciosa (Código Táctil):</b> En lugar de usar la voz, el capitán transmite las órdenes mediante toques en los hombros del penúltimo jugador, transmitiendo el código en cadena: 1 toque en el hombro derecho = girar a la derecha; 1 toque en el hombro izquierdo = girar a la izquierda; 2 toques simultáneos = detenerse.\n\n<b>Submarino con Recolección de Torpedos:</b> Se esparcen pelotas o globos en el terreno de juego. El primer jugador a ciegas debe ser guiado para agacharse y recoger los objetos sin colisionar con otros equipos.\n\n<b>Submarinos de Flota Mixta:</b> Se unen dos seisenas o patrullas para formar un super-submarino de 8 a 10 personas, poniendo a prueba la transmisión de señales a lo largo de una cadena más extensa.", "recomendaciones": "<b>Inspección del Terreno:</b> Asegurar que el área de juego esté completamente libre de baches, ramas bajas u obstáculos peligrosos para evitar tropiezos de los jugadores a ciegas.\n\n<b>Lanzamientos y Contacto Seguro:</b> Velar por que los toques entre submarinos sean siempre respetuosos y envolventes. Queda strictly prohibido empujar o correr bruscamente hacia los oponentes.\n\n<b>Rotación del Capitán:</b> Permitir que distintos integrantes de la patrulla asuman el rol de capitán en cada ronda para que todos experimenten tanto la conducción como la confianza de dejarse guiar.", "objetivos_educativos": [{"id": "cfa10133-c25c-4deb-aebe-a00f8fe3f7ef", "texto": "Comparto lo que tengo con mis compañeros y compañeras.", "texto_terminal": "Vive su libertad de un modo solidario, ejerciendo sus derechos, cumpliendo sus obligaciones y defendiendo igual derecho para los demás.", "rango_edad": "Infancia Media", "area": "Sociabilidad", "unidad": "Manada", "como_se_cumple": "Depositando mi confianza total en el timonel de mi seisena mientras camino a ciegas."}, {"id": "5cbe35dc-d15b-4070-9a36-5b0e652c7946", "texto": "Respeto las opiniones de los demás.", "texto_terminal": "Vive su libertad de un modo solidario, ejerciendo sus derechos, cumpliendo sus obligaciones y defendiendo igual derecho para los demás.", "rango_edad": "Infancia Tardía", "area": "Sociabilidad", "unidad": "Manada", "como_se_cumple": "Guiando a mis compañeros vendados con instrucciones claras y seguras."}, {"id": "a3d7abdf-ca3b-42b8-92b5-403958fb537c", "texto": "Procuro que respetemos a nuestras compañeros, cualquiera sea su manera de ser.", "texto_terminal": "Vive su libertad de un modo solidario, ejerciendo sus derechos, cumpliendo sus obligaciones y defendiendo igual derecho para los demás.", "rango_edad": "11 a 13 años", "area": "Sociabilidad", "unidad": "Tropa", "como_se_cumple": "Coordinando los desplazamientos de la patrulla mediante señales no verbales."}, {"id": "0d3af46a-d64c-4e59-a765-1f72dc41ba76", "texto": "Ayudo a mi patrulla en los compromisos que tomamos.", "texto_terminal": "Vive su libertad de un modo solidario, ejerciendo sus derechos, cumpliendo sus obligaciones y defendiendo igual derecho para los demás.", "rango_edad": "13 a 15 años", "area": "Sociabilidad", "unidad": "Tropa", "como_se_cumple": "Fortaleciendo la confianza recíproca entre todos los integrantes de la patrulla."}, {"id": "fce82191-77ea-444b-89d9-e33b62a323a5", "texto": "Procuro que respetemos a nuestras compañeras, cualquiera sea su manera de ser.", "texto_terminal": "Vive su libertad de un modo solidario, ejerciendo sus derechos, cumpliendo sus obligaciones y defendiendo igual derecho para los demás.", "rango_edad": "11 a 13 años", "area": "Sociabilidad", "unidad": "Compañía", "como_se_cumple": "Aceptando ser guiada a ciegas por mis compañeras en el terreno de juego."}, {"id": "944660c8-0093-4181-ba2c-5f95cc74ba47", "texto": "No me gusta cuando no se respetan los derechos humanos y lo digo.", "texto_terminal": "Vive su libertad de un modo solidario, ejerciendo sus derechos, cumpliendo sus obligaciones y defendiendo igual derecho para los demás.", "rango_edad": "13 a 15 años", "area": "Sociabilidad", "unidad": "Compañía", "como_se_cumple": "Asumiendo con responsabilidad el liderazgo de conducción del equipo."}, {"id": "5abfbe81-75e4-4444-b52d-38e59e8b6ec7", "texto": "Estoy siempre disponible para ayudar a los demás, incluso cuando se trata de tareas pesadas o poco agradables.", "texto_terminal": "Vive su libertad de un modo solidario, ejerciendo sus derechos, cumpliendo sus obligaciones y defendiendo igual derecho para los demás.", "rango_edad": "15 a 17 años", "area": "Sociabilidad", "unidad": "Avanzada", "como_se_cumple": "Fomentando un ambiente de alta confianza y cohesión en la patrulla."}, {"id": "b5a81328-5c07-41bd-a1ea-1ed401762841", "texto": "Vivo mi libertad de un modo solidario, ejerciendo mis derechos, cumpliendo mis obligaciones y defendiendo igual derecho para los demás.", "texto_terminal": "Vive su libertad de un modo solidario, ejerciendo sus derechos, cumpliendo sus obligaciones y defendiendo igual derecho para los demás.", "rango_edad": "17 a 20 años", "area": "Sociabilidad", "unidad": "Clan", "como_se_cumple": "Promoviendo el respeto por los derechos y la autonomía de cada caminante durante la navegación."}, {"id": "8c1cbf88-6e1d-496b-b789-9e0b767c8814", "texto": "Casi siempre estoy 